TOK = re.compile(r"[a-zа-яёәғқңөұүһі]+", re.I)

def lang(text):
    t = text.lower()
    toks = TOK.findall(t)
    kz = len(KZ_LET.findall(t)) * 0.5
    ru = 0
    for w in toks:
        if w in KZ_W: kz += 1
        elif w in RU_W: ru += 1
        elif re.search(r'(ге|ке|ға|ғе|қа|ка|да|де|та|те|дан|ден|тан|тен|нан|нен|мыз|міз|сыз|сіз|ымыз|ңыз|ңіз|ныз|низ|лар|лер|дар|дер|тар|тер)$', w) and len(w) > 4 and not re.search(r'(ться|ешь|ете|ают|ует|ого|ему|ами|ями|ость)$', w):
            kz += 0.3
        elif re.search(r'(ться|ется|ает|ешь|ете|ают|ует|ого|ому|ами|ями|ость|ение|ания|ный|ная|ное|ные|ться|ите|ать|ять|ить)$', w) and len(w) > 4:
            ru += 0.5
    if kz == 0 and ru == 0: return 'neutral'
    if kz >= 2 * ru and kz >= 1: return 'kz'
    if ru >= 2 * kz and ru >= 1: return 'ru'
    if kz > 0 and ru > 0: return 'mixed'
    return 'neutral'

