import unicodedata
def subst_len(t):
    t = ''.join(ch for ch in unicodedata.normalize('NFD', t) if not unicodedata.combining(ch))
    t = unicodedata.normalize('NFC', t)
    return len(re.sub(r'\s+', ' ', STRIP_O.sub(' ', t)).strip())
